function.arguments:
{"command":"cat << 'EOF' > outputs/t07_query.sparql
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT ?item ?label ?coord
WHERE {
  ?item wdt:P31 wd:Q11423 .    # art gallery
  ?item wdt:P625 ?coord .
  ?item skos:label ?label .
}
UNION
{
  ?item wdt:P31 wd:Q106290 .   # library
  ?item wdt:P625 ?coord .
  ?item skos:label ?label .
}
UNION
{
  ?item wdt:P31 wd:Q1572977 .  # monument
  ?item wdt:P625 ?coord .
  ?item skos:label ?label .
}
UNION
{
  ?item wdt:P31 wd:Q76 .       # museum
  ?item wdt:P625 ?coord .
  ?item skos:label ?label .
}
UNION
{
  ?item wdt:P31 wd:Q105315 .   # theatre building
  ?item wdt:P625 ?coord .
  ?item skos:label ?label .
}
EOF"}
